// Public, rarely-changing data - caching is appropriate and beneficial
async function ProjectsPage() {
  const response = await fetch('https://api.example.com/projects', {
    next: { revalidate: 3600 } // refresh at most once per hour - this
                                 // data is the same for every visitor
  });
  const projects = await response.json();
  return (
    <ul>
      {projects.map((project: Project) => <li key={project.id}>{project.name}</li>)}
    </ul>
  );
}

// Private, user-specific data - caching would be a genuine security/correctness bug
async function DashboardPage({ userToken }: { userToken: string }) {
  const response = await fetch('https://api.example.com/dashboard', {
    headers: { Authorization: `Bearer ${userToken}` },
    cache: 'no-store' // MUST be fresh per request - this response is
                        // specific to whichever user's token was sent,
                        // and must never be served to a different user
  });
  const data = await response.json();
  return <h1>Welcome back, {data.name}</h1>;
}

