// app/api/tasks/route.ts - handles GET and POST for '/api/tasks'
import { NextRequest, NextResponse } from 'next/server';

interface Task {
  id: number;
  title: string;
  completed: boolean;
}

let tasks: Task[] = [{ id: 1, title: 'Learn Next.js API Routes', completed: false }];

export async function GET() {
  return NextResponse.json({ success: true, data: tasks });
}

export async function POST(request: NextRequest) {
  const body = await request.json();

  if (!body.title || typeof body.title !== 'string') {
    return NextResponse.json(
      { success: false, error: 'A non-empty title is required' },
      { status: 400 }
    );
  }

  const newTask: Task = { id: Date.now(), title: body.title, completed: false };
  tasks.push(newTask);

  return NextResponse.json({ success: true, data: newTask }, { status: 201 });
}

// app/api/tasks/[id]/route.ts - handles DELETE for '/api/tasks/:id'
export async function DELETE(request: NextRequest, { params }: { params: { id: string } }) {
  const taskId = Number(params.id);
  const index = tasks.findIndex((t) => t.id === taskId);

  if (index === -1) {
    return NextResponse.json({ success: false, error: 'Task not found' }, { status: 404 });
  }

  tasks.splice(index, 1);
  return new NextResponse(null, { status: 204 });
}

