import { NextRequest, NextResponse } from 'next/server';

interface Note {
  id: number;
  content: string;
  authorId: string;
}

interface CreateNoteBody {
  content: string;
}

let notes: Note[] = [];

function getUserIdFromRequest(request: NextRequest): string | null {
  const authHeader = request.headers.get('authorization');
  if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
  return 'simulated-user-id'; // in a real app, this would verify a JWT
}

export async function GET() {
  return NextResponse.json({ success: true, data: notes });
}

export async function POST(request: NextRequest) {
  const userId = getUserIdFromRequest(request);
  if (!userId) {
    return NextResponse.json({ success: false, error: 'Authentication required' }, { status: 401 });
  }

  const body: CreateNoteBody = await request.json();

  if (!body.content || typeof body.content !== 'string' || body.content.trim() === '') {
    return NextResponse.json({ success: false, error: 'content is required' }, { status: 400 });
  }

  const newNote: Note = { id: Date.now(), content: body.content.trim(), authorId: userId };
  notes.push(newNote);

  return NextResponse.json({ success: true, data: newNote }, { status: 201 });
}

